type Entry = typeof DATA[number];

function getEntry(slug: string): Entry | undefined {
  return DATA.find((d) => d.slug === slug);
}

export async function generateStaticParams() {
  return DATA.map((d) => ({ slug: d.slug }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const entry = getEntry(slug);
  if (!entry) return { title: "점운 사주" };
  return {
    title: entry.title,
    description: entry.desc,
    openGraph: {
      title: entry.title,
      description: entry.desc,
      url: `https://jeomun.com/saju/guide/${entry.slug}`,
      siteName: "점운 사주",
      locale: "ko_KR",
      type: "website",
    },
    twitter: {
      card: "summary_large_image",
      title: entry.title,
      description: entry.desc,
    },
    alternates: {
      canonical: `https://jeomun.com/saju/guide/${entry.slug}`,
    },
  };
}

